WITH by_dimension AS (SELECT d.segment, d.country, src.plan, COUNT(*) AS rows_total, MIN(src.monthly_fee) AS min_monthly_fee, GROUPING_ID() AS level_id FROM subscriptions src LEFT JOIN customers d ON src.customer_id = d.id GROUP BY GROUPING SETS ((d.segment, d.country, src.plan), (d.segment))) SELECT segment, country, plan, rows_total, min_monthly_fee FROM by_dimension ORDER BY country DESC
